TP.register({id:"lp6-g3",lp:6,grade:"3",mode:"curriculum",checks:5,nextGrade:"4th grade",build(E){const F=E.F;const FLU_TITLE="The Night Walk";const FLU=["The town of Riverbend holds a night walk at the start of every new season. Riverbend is a small place with one bridge and one wide river.","In the afternoon, families carry paper lanterns down to the riverbank. Each lantern hangs from a long rope that runs from one end of the bridge to the other. By dark the rope holds more than a hundred of them.","Mei had the job of tying the knots. She looped the cord of each lantern twice, pulled it snug, and gave the rope a small tug to be sure.","The rope is strung in the morning, long before anyone brings a lantern. Two people stand on the bridge with the coil between them. One pays the rope out and the other walks it to the far rail. They pull it tight until it hums when you flick it. Mei’s grandmother says a loose rope makes a crooked line of light. A crooked line is the one thing the walk cannot have.","Every family writes one thing on the side of its lantern. Some write a hope for the season ahead and some write a job they mean to finish. Nobody reads them out loud. Mei wrote three words on hers and then turned the paper so the words faced the river.","When the last lantern was lit, the whole bridge glowed. People walked across slowly. Nobody ran. The river below carried the light downstream in long yellow lines. For a little while the water looked like a second sky."].join("\n\n");const STORY_TITLE="The Goal Card";const STORY=["On the first evening of the new season, Riverbend School gave every student a small blank card. The card was for one goal, something you wanted to get better at in the months ahead.","Tariq knew his goal right away. But he did not want to write it down. His goal was to swim the whole length of the pool without stopping. Last summer he had only made it halfway.","He held the card for a long time. Then he wrote it anyway, folded the card in half, and clipped it to the lantern rope with the others.","In the spring his teacher handed the cards back. Tariq unfolded his and read it twice. He had reached the far wall in July, three times. He kept the card in his pocket all the next week."].join("\n\n");const SKY_TITLE="The Sky Was Awake";const SKY=["Beatriz had waited all week for a clear night, and this one was perfect. Her grandmother called the sky over the hill a bowl of sparks.","They climbed up with two folding chairs and a thermos of warm milk. When they reached the top, Beatriz was out of breath.","“Take your time,” her grandmother said. “The stars are not going anywhere.”","For a while nobody said a word. The whole hill held its breath. Then a thin line of light slid across the sky and was gone.","“Did you see that?” Beatriz whispered. Her grandmother smiled. “That one was for you.”","Walking home, Beatriz felt like she was floating. She told her little brother about it four times before bed, and time flew."].join("\n\n");const LIGHT_TITLE="Old Light";const LIGHT=["Look up on a clear night and you will see stars. The light you see left those stars a long time ago.","Light moves fast. In one second, light travels about 186,000 miles. That is fast enough to circle the Earth seven times. Even so, the stars are so far away that their light takes years to reach us.","The closest star after our sun is called Proxima Centauri. Its light takes a little more than four years to get here. Many of the stars you can see are much farther away than that. Their light left before you were born.","So when you look at a star, you are looking at old light. You are seeing the star the way it was, not the way it is tonight."].join("\n\n");const PLAN_READ=["How Riverbend Plans the Night Walk.","Riverbend plans its night walk months ahead. A group of neighbors meets in the fall and splits up the work.","One team counts the lanterns and checks the ropes. A second team marks the walking path with chalk so that nobody steps off the bank. A third team cooks, because people get hungry standing out in the cold.","The planning takes about six weeks in all. By the night of the walk, nobody has to ask what to do. Every job already has a name next to it."].join("\n\n");const WORDS=["lantern","nightfall","riverbank","relight","unlit","misplace","brightness","hopeful","careless","direction","reflection","beautiful"];const CORD_PLOT=[["2",1],["2 1/2",3],["3",4],["3 1/2",2],["4",1]];function cordPlot(){const W=600,H=232,x0=70,x1=W-50,axisY=172,step=(x1-x0)/4;let s=`<svg viewBox="0 0 ${W} ${H}" width="580" role="img" aria-label="A line plot of cord lengths in inches. The scale runs 2, 2 and a half, 3, 3 and a half, 4. Above the marks there are 1 dot, 3 dots, 4 dots, 2 dots and 1 dot.">`;s+=`<rect x="3" y="3" width="${W-6}" height="${H-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;s+=`<text x="${W/2}" y="30" font-size="18" font-weight="700" text-anchor="middle" fill="var(--ink)">Cord lengths in inches</text>`;s+=`<line x1="${x0-22}" y1="${axisY}" x2="${x1+22}" y2="${axisY}" stroke="var(--fig-ink)" stroke-width="3"/>`;CORD_PLOT.forEach((v,i)=>{const x=x0+i*step;s+=`<line x1="${x}" y1="${axisY-8}" x2="${x}" y2="${axisY+8}" stroke="var(--fig-ink)" stroke-width="2.5"/>`;s+=`<text x="${x}" y="${axisY+32}" font-size="18" text-anchor="middle" fill="var(--ink)">${v[0]}</text>`;for(let k=0;k<v[1];k++)s+=`<circle cx="${x}" cy="${axisY-24-k*24}" r="8.5" fill="var(--sea)" stroke="var(--fig-ink)" stroke-width="2"/>`});return s+"</svg>"}const YEARS_TITLE="Counting the Years";const YEARS=["Distances between stars are so large that miles stop being useful. Astronomers measure them in light years instead. One light year is the distance light travels in one year.","Proxima Centauri is about 4.2 light years from us. A star that sits 900 light years away is showing you light that left it 900 years ago. The farther the star, the older the view.","Big telescopes gather light that is far older still. Some of the faint smudges in those pictures are galaxies whose light has been crossing space for billions of years."].join("\n\n");const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px;flex-wrap:wrap">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const checklist=items=>`<ul class="qlist" style="margin-top:14px">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const lookBack=(label,inner)=>`<details class="look-back" open><summary>Look back at ${label}</summary>${inner}</details>`;const group=(inner,label)=>`<div style="text-align:center">${inner}<p class="fig-label" style="margin:4px 0 0">${label}</p></div>`;const stackFig=inner=>`<div style="display:flex;flex-direction:column;gap:12px;align-items:center;margin-top:10px">${inner}</div>`;const lightHtml=small=>F.passage(LIGHT,LIGHT_TITLE,!!small);function noteBoxes(a,b){const bx=t=>`<div style="border:3px dashed var(--line);border-radius:16px;min-width:250px;min-height:100px;padding:8px 16px;background:var(--surface)"><p class="fig-label" style="margin:0;font-size:1.35rem">${t}</p></div>`;return`<div class="figure">${bx(a)}${bx(b)}</div>`}function unequalSquare(){const xs=[0,.12,.34,.78,1],S=220;let s=`<svg viewBox="0 0 ${S+8} ${S+8}" width="${S+8}" role="img" aria-label="A square cut into 4 strips that are not the same width">`;for(let k=0;k<xs.length-1;k++)s+=`<rect x="${4+xs[k]*S}" y="4" width="${(xs[k+1]-xs[k])*S}" height="${S}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;return s+"</svg>"}function stripSquare(n){const S=220,w=S/n;let s=`<svg viewBox="0 0 ${S+8} ${S+8}" width="${S+8}" role="img" aria-label="A square cut into ${n} equal strips">`;for(let k=0;k<n;k++)s+=`<rect x="${4+k*w}" y="4" width="${w}" height="${S}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;return s+"</svg>"}function splitRect(rows,a,b){const u=36,ox=92,oy=12,cols=a+b,W=ox+cols*u+18,H=oy+rows*u+46;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="A rectangle of square tiles, ${rows} rows tall and ${cols} columns long, with a heavy line splitting it into a block ${a} columns wide and a block ${b} columns wide">`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)s+=`<rect x="${ox+c*u}" y="${oy+r*u}" width="${u}" height="${u}" fill="${c<a?"var(--sea-soft)":"var(--gold)"}" fill-opacity="${c<a?"1":".5"}" stroke="var(--fig-ink)" stroke-width="2"/>`;s+=`<line x1="${ox+a*u}" y1="${oy}" x2="${ox+a*u}" y2="${oy+rows*u}" stroke="var(--fig-ink)" stroke-width="6"/>`;const t=(x,y,txt,an)=>`<text x="${x}" y="${y}" text-anchor="${an||"middle"}" font-size="20" font-weight="700" fill="var(--ink)">${txt}</text>`;s+=t(ox+a*u/2,oy+rows*u+30,a+" tiles")+t(ox+a*u+b*u/2,oy+rows*u+30,b+" tiles")+t(ox-12,oy+rows*u/2+7,rows+" tiles","end");return s+"</svg>"}function ellDeck(){const u=38,ox=60,oy=34,W=ox+6*u+74,H=oy+6*u+44;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="An L shaped deck on a grid of square meters. The bottom block is 6 squares long and 2 squares tall. A block 3 squares long and 4 squares tall sits on top of its left end.">`;for(let r=0;r<6;r++)for(let c=0;c<6;c++){if(!(r>=4||c<3))continue;s+=`<rect x="${ox+c*u}" y="${oy+r*u}" width="${u}" height="${u}" fill="var(--sea-soft)" stroke="var(--fig-ink)" stroke-width="2"/>`}const t=(x,y,txt,an)=>`<text x="${x}" y="${y}" text-anchor="${an||"middle"}" font-size="20" font-weight="700" fill="var(--ink)">${txt}</text>`;s+=t(ox+1.5*u,oy-10,"3 m")+t(ox+3*u,oy+6*u+30,"6 m")+t(ox-12,oy+2*u+7,"4 m","end")+t(ox+6*u+12,oy+5*u+7,"2 m","start");return s+"</svg>"}const STOPS=[{id:1,title:"Lantern Label Words",short:"Label Words",parts:[{std:["RF.3.3"],kind:"words",words:WORDS,n:12,dur:75,dir:"Read each word out loud. Look for a part you already know at the start or the end of the word.",desc:"reading longer words with prefixes, suffixes, and more than one syllable",key:["Read each word in order: lantern, nightfall, riverbank, relight, unlit, misplace, brightness, hopeful, careless, direction, reflection, beautiful.","Watch for: compound words (nightfall, riverbank), prefixes re-, un-, mis- (relight, unlit, misplace), suffixes -ness, -ful, -less (brightness, hopeful, careless), the -tion ending (direction, reflection), and an irregular spelling where the letters eau spell the long u sound (beautiful).","Optional word-part check: ask what re- does in relight (light it again) and what -less does in careless (without care)."]}]},{id:2,title:"The Lantern Line",short:"Rope Lines",parts:[{std:["3.NF.A.2"],dur:140,dir:"Look at the ropes. Answer out loud. Tell how you know.",desc:"naming a fraction as a number on a number line and placing fractions on a number line",html:()=>`<p class="big" style="margin-top:0">Each rope runs from one bank of the river to the other. The 0 is the near bank. The 1 is the far bank. The dot is one lantern on the rope.</p>`,fig:()=>stackFig(group(F.numberLine({min:0,max:1,step:.25,hideNumbers:true,ticks:[[0,"0"],[1,"1"]],marks:[.75],width:560}),"Rope A, cut into 4 equal parts")+group(F.numberLine({min:0,max:1,step:1/6,hideNumbers:true,ticks:[[0,"0"],[1,"1"]],marks:[1/6],width:560}),"Rope B, cut into 6 equal parts")+group(F.numberLine({min:0,max:2,step:.5,labelEvery:1,marks:[1.5],width:560}),"Rope C, cut into halves")),qs:["Rope A is cut into 4 equal parts. What fraction of the way across is the lantern?","Rope B is cut into 6 equal parts. Name the fraction where the lantern hangs. What is one part of this rope called?","A rope runs from 0 to 1. It is cut into 8 equal parts. How many jumps of 1/8 does it take? You get from 0 to 5/8.","Rope C goes from 0 to 2 and is cut into halves. Name the fraction where the lantern hangs.","Tell your teacher how to draw a number line from 0 to 1 and mark 2/3 on it."],key:["3/4. The rope from 0 to 1 is cut into 4 equal parts and the lantern sits at the end of the third part. Partial: 3/4 right with no account of the equal parts is approaching. (3.NF.A.2)","1/6. One part of this rope is 1/6, because the whole from 0 to 1 is cut into 6 equal parts. Partial: the fraction right with no name for one part is approaching. (3.NF.A.2)","5 jumps. Each jump is 1/8 of the way, so 5 jumps land on 5/8. Partial: 5 given with no account of the size of a jump is approaching. (3.NF.A.2)","3/2. Accept 1 1/2. Counting halves from 0 gives 1/2, 2/2, 3/2, and the lantern is on the third one. Partial: 3/4 treats the whole 0 to 2 line as one whole and does not count. (3.NF.A.2)","Cut the space from 0 to 1 into 3 equal parts, then count 2 parts from 0 and mark that point. The mark goes at the end of the second part, not at the second tick counting the 0. Partial: counting ticks from the 0 instead of counting parts is the slip to watch and is approaching. (3.NF.A.2)"]}]},{id:3,title:"Read the Night Walk",short:"Read Aloud",parts:[{std:["RF.3.4"],kind:"read",n:0,label:"words read correctly",dur:175,dir:"Read the story out loud. Use your best reading voice.",desc:"a grade-level story read aloud",html:()=>F.passage(FLU,FLU_TITLE),key:["__WC__ words, not counting the title. Time 1 minute and mark errors and self-corrections on your own copy. Let the student finish the passage.","Winter grade 3 benchmark: about 97 words correct per minute (Hasbrouck and Tindal 2017, winter 50th percentile). 25th percentile is about 79. The passage length is set from the highest grade 3 figure on that same table, the spring 90th percentile of about 166 words correct per minute, so the minute ends before the text does even for the fastest reader and the score measures the reading rather than the length of the page.","Note pace, phrasing, and expression. Listen for the three-part list in the sentence about the knots, and for a slower voice in the last paragraph."]}]},{id:4,title:"Old Light",short:"Star Light",parts:[{std:["RI.3.1"],dur:125,dir:"Read the text. Then answer out loud. Look back at the text to prove each answer.",desc:"questions about an informational text answered with the exact words in the text",html:()=>lightHtml(true),fig2:()=>F.row([F.icon("star",120),"The light you see is old light"]),qs:["How far does light travel in one second? Read the words from the text.","What is the closest star after our sun? Read the sentence that tells you.","How long does the light from that star take to reach us? Find the words in the text.","Why does the text call starlight old light? Read the sentence that explains it.","Your turn to be the teacher. Ask one question that this text answers. Start with How, What, or Why."],key:["About 186,000 miles. Reads “In one second, light travels about 186,000 miles.” (RI.3.1)","Proxima Centauri. Reads “The closest star after our sun is called Proxima Centauri.” (RI.3.1)","A little more than four years. Reads “Its light takes a little more than four years to get here.” (RI.3.1)","Because the light left the star long ago. Reads “You are seeing the star the way it was, not the way it is tonight,” or the first paragraph. (RI.3.1)","Asks a question the text can answer, such as: How fast does light move? What is the closest star after our sun? Why does starlight take years to reach us? (RI.3.1, asks questions)"]}]},{id:5,title:"Which Lantern Holds More?",short:"Compare",parts:[{std:["3.NF.A.3"],dur:150,dir:"Answer out loud. Tell how you know. You can draw on your paper to show your thinking.",desc:"explaining equivalent fractions and comparing fractions by reasoning about their size",html:()=>`<p class="big" style="margin-top:0">The crew writes down how full each lantern is as a fraction. Bar A and Bar B below are the same size. So they stand for two lanterns that are the same size.</p>`,fig:()=>`<div class="figure" style="gap:28px;align-items:flex-end">${group(F.fracBar(2,1,{width:300}),"Bar A")}${group(F.fracBar(4,2,{width:300}),"Bar B")}</div>`,qs:["Which is more oil in the same lantern, 2/3 or 2/6? How do you know?","Which is more, 5/8 of a lantern or 3/8 of the same lantern? How do you know?","Look at Bar A and Bar B. Are the shaded parts equal? Say it as two fractions that are equal.","Name a fraction that is equal to 3/6.","Write 1 whole as a fraction with 4 as the bottom number. Then write the whole number 5 as a fraction.","Two lanterns are not the same size. Noor says 1/2 of the small lantern holds more than 1/2 of the big lantern. Can you compare those two halves? Tell why or why not."],key:["2/3. The top numbers are the same, so compare the piece sizes: thirds are bigger pieces than sixths, so 2 thirds is more than 2 sixths. Partial: naming 2/3 with no reason about the size of the pieces is approaching. (3.NF.A.3)","5/8. The pieces are the same size, so the one with more pieces is more. Partial: naming 5/8 with no reason is approaching. (3.NF.A.3)","Yes, they are equal. 1/2 = 2/4. The bars are the same size and the shaded parts cover the same amount. Partial: saying yes with no pair of equal fractions written is approaching. (3.NF.A.3)","1/2. Also correct: 2/4. Partial: 3/6 given back does not count, since a different name is what is asked. (3.NF.A.3)","4/4 and 5/1. Partial: one of the two given is approaching. (3.NF.A.3)","No. Fractions can only be compared when they name parts of the same whole. The lanterns are different sizes, so 1/2 of one is not the same amount as 1/2 of the other, and the fractions alone cannot settle it. Partial: saying no with nothing said about the same whole is approaching. (3.NF.A.3)"]}]},{id:6,title:"The Goal Card",short:"Goal Card",parts:[{std:["RL.3.1"],dur:125,dir:"Read the story. Then answer out loud. Look back at the story to prove each answer.",desc:"asking and answering story questions using the exact words in the text",html:()=>F.passage(STORY,STORY_TITLE,true),qs:["What was the card for? Read the words from the story.","What was Tariq's goal? Read the sentence that tells you.","How far had Tariq swum the summer before? Find the words in the story.","What did Tariq do with the card after he wrote on it? Read the words that tell you.","Your turn to be the teacher. Ask one question that this story answers. Start with Who, What, or Why."],key:["Reads “The card was for one goal, something you wanted to get better at in the months ahead.” (RL.3.1)","Reads “His goal was to swim the whole length of the pool without stopping.” (RL.3.1)","Halfway. Reads “last summer he had only made it halfway.” (RL.3.1)","Reads “folded the card in half, and clipped it to the lantern rope with the others.” (RL.3.1)","Asks a question the story can answer, such as: Who handed the cards back? What did Tariq write on his card? Why did he not want to write it down? (RL.3.1, asks questions)"]}]},{id:7,title:"Tile the Square",short:"Tiles",parts:[{std:["3.MD.C.7"],dur:175,dir:"Answer out loud. For numbers 4 and 6, write your work on your paper. Then hold it up.",desc:"relating the area of a rectangle to multiplication and addition",html:()=>`<p class="big" style="margin-top:0">The town is laying square tiles in the square by the bridge so the night walk has a dry path. Every tile is 1 square meter.</p>`,fig:()=>`<div class="figure" style="gap:30px;align-items:flex-end">${group(F.gridRect(4,6,0,{cell:38}),"Tiled corner")}${group(splitRect(5,4,3),"Split path")}</div>`,qs:["Look at the tiled corner. How many tiles cover it? Write the multiplication equation that matches the picture.","A banner is 3 meters tall and 8 meters long. What is its area? Say the unit.","Look at the split path. Find the area of the shaded block and the area of the gold block. Then add them. Now multiply the whole length by the whole width. Do you get the same answer?","The lantern deck is an L shape. The bottom block is 6 meters by 2 meters and the block above it is 3 meters by 4 meters. What is the total area?","One rug is 7 feet by 4 feet. Another rug is 6 feet by 5 feet. Which rug has more area?","A rectangle has an area of 32 square feet. One side is 8 feet long. How long is the other side?"],fig2:()=>F.row([ellDeck(),"The L shaped lantern deck, in square meters"]),key:["24 tiles. 4 × 6 = 24, or 6 × 4 = 24. The picture shows 4 rows of 6 tiles. Partial: the count right with no multiplication equation written is approaching. (3.MD.C.7)","24 square meters. 3 × 8 = 24. The unit has to be square meters, not meters. Partial: 24 with no square unit named is approaching. (3.MD.C.7)","Shaded block 5 × 4 = 20. Gold block 5 × 3 = 15. 20 + 15 = 35. The whole rectangle is 5 × 7 = 35. Yes, the two ways match. Partial: the two blocks right with no whole-rectangle check is approaching. (3.MD.C.7, area of a 5 by 4 plus 3 rectangle is 5 × 4 plus 5 × 3)","24 square meters. 6 × 2 = 12 and 3 × 4 = 12, then 12 + 12 = 24. Area adds up when a shape is cut into rectangles that do not overlap. Partial: one of the two blocks worked out is approaching. (3.MD.C.7)","The 6 by 5 rug. 7 × 4 = 28 square feet and 6 × 5 = 30 square feet, and 30 is more than 28. Partial: naming the rug with only one area worked out is approaching. (3.MD.C.7)","4 feet. 8 × 4 = 32, so the missing side is 4. Partial: 24 feet from taking 32 − 8 subtracts where the problem divides and does not count. (3.MD.C.7)"]}]},{id:8,title:"A Bowl of Sparks",short:"Sparks",parts:[{std:["RL.3.4"],dur:125,dir:"Read the story. Then answer out loud. Use the story to explain each answer.",desc:"word and phrase meanings in a story, telling literal from nonliteral language",html:()=>F.passage(SKY,SKY_TITLE,true),qs:["Her grandmother calls the sky a bowl of sparks. Is the sky really a bowl of sparks? What does she mean?","The story says the whole hill held its breath. Can a hill hold its breath? What does this really tell you?","What does the word slid mean in “a thin line of light slid across the sky”?","Beatriz felt like she was floating. Was she really floating? What does this tell you about her?","One of these means exactly what the words say and one does not. Which is which? A: “She told her little brother about it four times.” B: “Time flew.”"],key:["Nonliteral. The stars look like bright sparks scattered across a wide curved sky, the way sparks would sit in a round bowl. (RL.3.4, nonliteral language)","Nonliteral. It means everyone on the hill went completely quiet and still. The story says “nobody said a word” right before it. (RL.3.4, nonliteral language)","Moved smoothly and quickly, in one line, without a sound. The next words, “and was gone,” show how fast it was. (RL.3.4, meaning of a word as used in the text)","Nonliteral. She was so happy and light that walking felt easy, as if her feet were barely touching the ground. (RL.3.4, nonliteral language)","A is literal, because she really did tell him four times. B is nonliteral, because time cannot fly. It means the time passed very quickly. (RL.3.4, literal and nonliteral)"]}]},{id:9,title:"Cut the Paper Panels",short:"Panels",parts:[{std:["3.G.A.2"],dur:160,dir:"Look at the panels. Answer out loud. Tell how you know.",desc:"cutting shapes into parts with equal areas and naming one part as a unit fraction of the whole",html:()=>`<p class="big" style="margin-top:0">A paper lantern is built from flat panels. The crew cuts each panel into parts. Every helper gets the same amount of paper to fold.</p>`,fig:()=>`<div class="figure" style="gap:24px;align-items:flex-end">${group(F.gridRect(2,2,0,{cell:110}),"Panel A")}${group(stripSquare(6),"Panel B")}${group(F.fracCircle(3,0,180),"Panel C")}${group(unequalSquare(),"Panel D")}</div>`,qs:["Panel A is cut into 4 parts with equal areas. What fraction of the whole panel is one part?","Panel B is cut into equal strips. What fraction of the whole panel is one strip?","Panel C is a round panel cut into equal parts. What fraction of the whole panel is one part?","Panel D is cut into 4 parts. Can you call one of those parts 1/4 of the panel? Tell why or why not.","A whole banner has an area of 8 square feet and is cut into 8 parts with equal areas. What fraction of the banner is one part. What is the area of one part?","Tell your teacher two different ways to cut a square panel into 4 parts with equal areas. What fraction of the square is each part?"],key:["1/4. The panel is cut into 4 parts with the same area, so one part is 1 of 4 equal parts of the whole. Partial: 4 given with no fraction form is approaching. (3.G.A.2)","1/6. There are 6 equal strips, so one strip is 1/6 of the panel. Partial: 6 given with no fraction form is approaching. (3.G.A.2)","1/3. The round panel is cut into 3 equal parts, so one part is 1/3 of it. Partial: 3 given with no fraction form is approaching. (3.G.A.2)","No. The 4 strips do not have the same area, and a fourth has to be 1 of 4 parts with equal areas. Partial: saying no with nothing said about equal areas is approaching. (3.G.A.2)","1/8 of the banner, and 1 square foot. 8 square feet split into 8 equal parts gives 1 square foot for each part. Partial: one of the fraction and the area given is approaching. (3.G.A.2)","Any two correct ways, such as 4 strips side by side, a 2 by 2 grid of smaller squares, 4 rows across, or two cuts corner to corner making 4 triangles. Each part is 1/4 of the square. Partial: one correct way given is approaching. (3.G.A.2)"]}]},{id:10,title:"Fix the Notice",short:"Fix It",parts:[{title:"One Mistake Each",std:["L.3.1"],dur:80,dir:"Each line from the town notice has one mistake. Say the whole line out loud the right way.",desc:"fixing spoken grammar mistakes (plurals, verb tense, agreement, comparing words, pronouns)",qs:["The childs ran down to the river.","Last night we singed a song by the water.","Three lanterns was hanging over the bridge.","This is the most brightest lantern on the whole rope.","Omar put on his coat, but he forgot their hat."],key:["The children ran down to the river. (L.3.1, irregular plural noun)","Last night we sang a song by the water. (L.3.1, irregular past tense verb)","Three lanterns were hanging over the bridge. (L.3.1, subject-verb agreement)","This is the brightest lantern on the whole rope. (L.3.1, superlative adjective)","Omar put on his coat, but he forgot his hat. (L.3.1, pronoun that matches its noun)"]},{title:"Build a Line",std:["L.3.1"],dur:60,dir:"Answer out loud. Say whole sentences.",desc:"spoken grammar items (joining sentences, future tense, adverbs, abstract nouns)",qs:["Join these two sentences into one. Use because: Mei carried a lantern. The path was dark.","Change this sentence so it tells about tomorrow. The town lights the lanterns. Then it sings by the river.","Which word fits? The rope swayed ____ in the wind. Is it quiet or quietly?","Which word names something you cannot see or touch: river, lantern, or hope?"],key:["Mei carried a lantern because the path was dark. (L.3.1, subordinating conjunction that joins a cause to a result)","The town will light the lanterns and will sing by the river. Both verbs need to change, so accept “will light the lanterns and sing by the river” too. (L.3.1, simple future tense)","quietly (L.3.1, adverb that tells how)","hope (L.3.1, abstract noun)"]}]},{id:11,title:"Listen to the Plan",short:"Listen",parts:[{std:["SL.3.2"],n:5,dur:130,dir:"Listen while your teacher reads. Then answer out loud. For the last two, use the graph.",desc:"main ideas and supporting details from a text read aloud and from a graph",read:PLAN_READ,html:()=>`<p class="big" style="margin-top:0">Your teacher will read you a short report about the town's plan. Listen for the big idea and for the details that back it up. Then look at the graph.</p>`,fig:()=>F.row([F.barGraph({title:"Lanterns on the rope",cats:["West end","Middle","East end"],vals:[40,70,50],max:80,step:10}),"Where the lanterns hang on the bridge"]),qs:["What is the main idea of the report your teacher read?","Give two details from the report that back up that main idea.","How long does the planning take in all? Which part of the report told you?","Look at the graph. What is the main idea the graph shows?","Give one supporting detail from the graph."],key:["Main idea: Riverbend plans the night walk far ahead of time by splitting the work into separate jobs, so the night itself runs smoothly. (SL.3.2, main idea of a text read aloud)","Any two details: a group of neighbors meets in the fall and splits up the work; one team counts lanterns and checks ropes; one team marks the path with chalk; one team cooks; the planning takes about six weeks; by the night of the walk every job already has a name next to it. (SL.3.2, supporting details)","About six weeks. It came from the last part of the report. (SL.3.2, supporting detail)","The lanterns are not spread evenly along the bridge. The middle of the bridge holds the most. (SL.3.2, main idea presented visually and quantitatively)","Any detail read correctly from the graph: the middle has 70 lanterns, the east end has 50, the west end has 40, or the west end has the fewest. (SL.3.2, supporting detail presented quantitatively)"]}]},{id:12,title:"Star Notes",short:"Notes",parts:[{std:["W.3.8"],n:3,label:"checks met",dur:100,dir:"Read the text. Write your notes on your paper and hold it up.",desc:"taking brief notes from a text and sorting them into given categories",html:()=>`${lightHtml(true)}<p class="big">Make two boxes on your paper. Label them like the boxes below. Write two short notes from the text in each box.</p>${noteBoxes("How fast light moves","How far away the stars are")}<p class="small" style="text-align:center;font-size:1.2rem">A note is just a few words. You do not need a whole sentence.</p>`,key:["Speed box: two facts, such as light is fast, about 186,000 miles in one second, circles Earth seven times in a second. (W.3.8, sorts evidence into the given category)","Distance box: two facts, such as starlight takes years to arrive, Proxima Centauri is the closest star after the sun, its light takes a little more than four years, some starlight left before you were born. (W.3.8, sorts evidence into the given category)","Notes are brief: a few words or a short phrase, not a whole sentence copied out of the text. (W.3.8, brief notes)"]}]},{id:13,title:"New Year Writer",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Lanterns or benches?"},std:["W.3.1"],n:4,label:"checks met",dur:200,dir:WRITE_DIR,desc:"an opinion writing piece",html:()=>`<p class="big">Riverbend has saved enough money for one new thing this year. The town can buy 100 more paper lanterns for the rope, or it can build six new benches along the river path. More lanterns would make the bridge brighter on the night of the walk. New benches would give people a place to sit by the river all year long.</p><p class="big">Which should the town pick? Write your opinion and give reasons. Write 4 or 5 sentences.</p>${checklist(["Say your opinion in the first sentence","Give two reasons for it","Use a linking word: because, since, also, for example","End with a closing sentence"])}`,key:["Introduces the topic and states a clear opinion about lanterns or benches (W.3.1)","Gives reasons that support the opinion, such as a brighter bridge for the walk or a place to sit all year (W.3.1)","Uses linking words such as because, since, also, for example, therefore (W.3.1)","Ends with a concluding sentence (W.3.1)"]},{alt:{group:"write",key:"facts",label:"Explain",icon:"📘",hint:"Teach about old light"},std:["W.3.2"],n:4,label:"checks met",dur:200,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">Write to teach someone why the light we see from a star is called old light. Use facts from the text. Write 5 or 6 sentences.</p>${checklist(["Start with a sentence that names your topic","Give facts from the text, and add a detail to at least one of them","Use linking words: also, another, because","End with a closing sentence"])}${lookBack("the text",lightHtml(true))}`,key:["Introduces the topic: why starlight is called old light (W.3.2)","Develops the topic with facts from the text, such as about 186,000 miles a second, light still takes years to arrive, Proxima Centauri takes a little more than four years, some starlight left before the reader was born, and adds at least one detail (W.3.2)","Uses linking words such as also, another, and, because (W.3.2)","Ends with a concluding sentence (W.3.2)"]},{alt:{group:"write",key:"story",label:"Story",icon:"✨",hint:"A clear night on the hill"},std:["W.3.3"],n:4,label:"checks met",dur:200,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">You climb a hill on a clear night with someone in your family to watch the sky. Write the story of what you see and what happens up there. Write 5 or 6 sentences.</p>${pills("First","Next","After that","Finally")}${checklist(["Tell who is there and where it happens","Tell what happens in order","Add a detail that helps the reader picture it, and tell what someone says or feels","Give your story an ending"])}`,key:["Sets up the situation and who is in the story (W.3.3)","Events happen in a clear order, with time words such as first, next, after that, finally (W.3.3)","Uses descriptive details and tells thoughts or feelings, or uses dialogue (W.3.3)","Has an ending that wraps up the story (W.3.3)"]}]},{id:14,title:"Crates and Shares",short:"Crates",parts:[{std:["3.OA.A.1","3.OA.A.2"],n:4,dur:60,dir:"Look at the crates. Answer out loud.",desc:"interpreting a product as equal groups and a quotient as a share size or a number of shares",html:()=>`<p class="big" style="margin-top:0">The Riverbend crew packs the lanterns into crates before carrying them down to the bridge.</p>`,fig:()=>F.row([F.array(6,4,"lantern"),"6 crates, 4 lanterns in each"]),qs:["The picture shows 6 rows of 4. What does 6 × 4 mean here, and what is the total?","Describe a different thing at the night walk that 5 × 7 could stand for.","The crew shares 24 lanterns equally among 4 crates. What does 24 ÷ 4 tell you here?","Now the crew packs 24 lanterns into crates that hold 6 each. What does 24 ÷ 6 tell you here?"],key:["6 groups of 4 lanterns each. The total is 24. Look for the words groups of, or a retelling that keeps the 6 as the number of crates. Partial: 24 given with no account of what the numbers mean is approaching. (3.OA.A.1)","Any context with 5 equal groups of 7, or 7 equal groups of 5, and a total of 35: 5 ropes with 7 lanterns each, 5 rows of 7 chairs, 7 helpers each carrying 5 lanterns. Partial: a context with the right numbers but no equal groups is approaching. (3.OA.A.1, describing a context for a product)","How many lanterns go in each crate: 6. The 4 is the number of shares and the answer is the size of one share. Partial: 6 given with no account of what it counts is approaching. (3.OA.A.2)","How many crates are needed: 4. Here the 6 is the size of each share and the answer is the number of shares. The same numbers, a different question. Partial: 4 given with no account of what it counts is approaching. (3.OA.A.2)"]}]},{id:15,title:"Two Steps and a Check",short:"Two Steps",parts:[{title:"Two Steps",std:["3.OA.D.8"],n:4,dur:150,dir:"Solve on your paper. Show your work and hold it up.",desc:"two-step word problems with an equation and an estimate",html:()=>`<p class="big" style="margin-top:0">The crew started the evening with 128 lanterns on the cart. They hung 56 of them on the west end of the bridge and 39 on the east end.</p>`,qs:["The crew also set out 4 trays of paper stars with 7 stars on each tray. 9 of the stars went on the gate. How many stars are left? Write an equation with a letter for the unknown. Then solve.","How many lanterns are left on the cart? Estimate first by rounding each number to the nearest ten. Then solve."],key:["Problem 1 equation with a letter: 4 × 7 - 9 = p, or 4 × 7 = 28 and 28 - 9 = p. Both steps have to be there, and the unknown has to be a letter, not a blank. Partial: the right answer with no letter for the unknown is approaching. (3.OA.D.8)","Problem 1 answer: 19 stars. Partial: 28 stops at the trays and leaves the 9 out, so it is approaching. (3.OA.D.8)","Problem 2 estimate: about 30, from 130 - (60 + 40) = 30. The exact answer has to be compared to it and called reasonable. Partial: any rounding that lands near 30 counts, and no estimate at all is approaching. (3.OA.D.8, rounding to check)","Problem 2 answer: 56 + 39 = 95, then 128 - 95 = 33 lanterns. Or: 128 - (56 + 39) = n worked as one equation. Partial: 72 takes off only one of the two amounts and is approaching. (3.OA.D.8)"]},{title:"Round It",std:["3.NBT.A.1"],n:3,dur:60,dir:"Answer out loud.",desc:"rounding whole numbers to the nearest ten and to the nearest hundred",qs:["Round 128 to the nearest ten. Then round 128 to the nearest hundred.","Round 847 to the nearest hundred.","Round 365 to the nearest ten. Then round 365 to the nearest hundred."],key:["130 to the nearest ten, because 8 ones rounds up. 100 to the nearest hundred, because 28 is less than 50. Partial: one of the two roundings right is approaching. (3.NBT.A.1)","800. 47 is less than 50, so the hundreds digit stays. Partial: 900 rounds up when the tens digit is 4 and does not count. (3.NBT.A.1)","370 to the nearest ten, because 5 ones rounds up. 400 to the nearest hundred, because 65 is more than 50. Partial: one of the two roundings right is approaching. (3.NBT.A.1)"]}]},{id:16,title:"One Part of the Banner",short:"Unit Parts",parts:[{std:["3.NF.A.1"],n:3,dur:45,dir:"Look at the two banners. Answer out loud.",desc:"understanding a unit fraction as one of b equal parts and a fraction a/b as a copies of that part",html:()=>`<p class="big" style="margin-top:0">Each banner is one whole banner, cut into equal parts.</p>`,fig:()=>`<div class="figure" style="gap:28px;align-items:flex-end">${group(F.fracBar(6,1,{width:300}),"Banner A")}${group(F.fracBar(6,5,{width:300}),"Banner B")}</div>`,qs:["Banner A is cut into 6 equal parts and 1 part is shaded. What fraction of the whole banner is shaded?","Banner B shows 5/6. What does the 6 tell you? What does the 5 tell you?","Finish this sentence: 3/4 means 3 parts, and each one of those parts is ____."],key:["1/6. The whole is cut into 6 equal parts and 1 of them is shaded. Partial: 6 given with no fraction form is approaching. (3.NF.A.1)","The 6 tells how many equal parts the whole banner is cut into. The 5 tells how many of those parts you have. Partial: one of the two numbers explained is approaching. (3.NF.A.1)","1/4 of the whole, or one fourth. 3/4 is 3 copies of the part 1/4. Answers like three out of four pieces only count if the student says the pieces are equal parts of the same whole. Partial: three out of four pieces is approaching unless the student says the pieces are equal parts of the same whole. (3.NF.A.1)"]}]},{id:17,title:"Measure the Cords",short:"Cords",parts:[{std:["3.MD.B.4"],n:4,dur:105,dir:"Look at the ruler and the line plot. Answer out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"measuring a length to the nearest half inch on a ruler marked in fourths, generating measurements of real objects with a ruler, and reading a line plot of those measurements",html:()=>`<p class="big" style="margin-top:0">Every lantern hangs from a short cord. The crew measured the cords and plotted them.</p>`,fig:()=>F.row(F.ruler({length:4,unit:"in",item:2.5,itemLabel:"one cord",parts:4})),fig2:()=>F.row(cordPlot()),qs:["How long is the cord on the ruler?","On the line plot, how many cords were 3 inches long?","How many cords were measured in all. How many of them were longer than 3 inches?","Now you are the measurer. Find three small things at your table. Something like a pencil. Or an eraser. Or a paper clip. Measure each one with your ruler. Say what each thing is. Say how long it is, to the nearest quarter inch."],key:["2 1/2 inches. The ruler is marked in fourths, so the cord ends on the half mark just past the 2. Starting the cord at the 1 instead of the 0 gives 1 1/2, which is the usual error. Partial: 1 1/2 comes from starting at the 1 instead of the 0 and does not count. (3.MD.B.4)","4 cords. Count the dots stacked above the 3. Partial: counting the dots above a different number does not count. (3.MD.B.4)","11 cords in all (1 + 3 + 4 + 2 + 1). 3 of them were longer than 3 inches: the 2 at 3 1/2 inches and the 1 at 4 inches. Partial: the total right with the count of longer cords missing is approaching. (3.MD.B.4)","Three objects of the student's own choosing, each measured and named with a length. Watch the 0 end of the ruler line up with the end of the object, and listen for a length to the nearest quarter inch (a whole, 1/4, 1/2, or 3/4) with the unit inches said. Write the three objects and lengths on the record sheet. Or: any three objects count, since these are the student's own data and there is no fixed answer. Partial: three lengths given but all rounded to whole inches, or the ruler started at the 1 instead of the 0, is approaching. (3.MD.B.4)"]}]},{id:18,title:"Two Writers, One Topic",short:"Two Texts",parts:[{std:["RI.3.9"],n:3,dur:55,dir:"Read the second text. You read the first one earlier. Then answer out loud.",desc:"comparing and contrasting the main points and key details of two texts on the same topic",html:()=>`${F.passage(YEARS,YEARS_TITLE,true)}${lookBack("Old Light",lightHtml(true))}`,qs:["What point do both texts make about starlight?","Each text measures the distance a different way. How does Old Light do it. How does Counting the Years do it?","Name one key detail that is in Counting the Years and not in Old Light."],key:["Both say the light you see from a star left it long ago, so you are seeing the star as it was, not as it is now. (RI.3.9, the most important point shared by two texts)","Old Light measures in miles and seconds: light travels about 186,000 miles in one second. Counting the Years measures in light years: one light year is the distance light travels in a year. (RI.3.9, contrasting how two texts present the same topic)","Any detail only in the second text: distances in miles stop being useful, a light year is a distance and not a time, a star 900 light years away shows light that left 900 years ago, big telescopes gather light from galaxies that has crossed space for billions of years. Proxima Centauri is in both texts, so naming that one does not count. (RI.3.9, key details)"]}]},{id:19,title:"Tell It Out Loud",short:"Report",parts:[{std:["SL.3.4"],n:3,label:"checks met",dur:45,dir:"Talk for about a minute. Speak clearly and take your time.",desc:"reporting on an experience out loud with facts and descriptive details, at an understandable pace",html:()=>`<p class="big">Tell about a time you were outside after dark, or tell about one thing you want to get better at this year and how you will work at it.</p>${checklist(["Say what it is in your first sentence","Give facts: where, when, who was there","Add details that help your listener picture it","Speak clearly and slow enough to follow"])}`,key:["Reports on the topic or experience with facts that fit it: where it was, when, who was there, what happened. (SL.3.4, appropriate facts)","Adds relevant descriptive details that help the listener picture it, such as what it looked like, sounded like, or felt like. Details that wander off the topic do not count. (SL.3.4, relevant descriptive details)","Speaks clearly at an understandable pace: loud enough to hear, not rushed, sentences finished. (SL.3.4, speaking clearly at an understandable pace)"]}]},{id:20,title:"A Nose at the Door",short:"Senses",parts:[{title:"Sense, Brain, Act",std:["3-LS1-1"],n:3,dur:90,dir:"Answer out loud. For the last one, draw your model on your paper and hold it up.",desc:"using a model to show how an animal takes in information, processes it, and responds",html:()=>`<p class="big">A dog waits outside the community hall. A big pot of soup cooks inside. His nose lifts. He sniffs twice. He trots around to the kitchen door rather than the front door.</p>
     <div class="figure">${F.icon("dog",96)}${F.icon("nose",80)}${F.icon("soup",88)}</div>`,qs:["Which sense took in the information about the soup? Which body part did that work?","He chose the kitchen door, not the front door. What had to happen inside him for him to choose?","Draw a model of this with three boxes and two arrows. Label every box."],key:["Smell, with his nose. (3-LS1-1)","The smell information went to his brain, and the brain worked out which direction the smell was strongest in and decided which door to go to. (3-LS1-1)","Three parts in order with arrows: nose or smells the soup, then brain, then goes to the kitchen door. The order is what is rated. A model with nothing in the middle is incomplete. (3-LS1-1)"]},{title:"The Whole Colony",std:["3-LS2-1"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"building an argument from data that forming a group helps animals survive",html:()=>`<p class="big">A class set out the same piece of bread for ants at two spots and watched for an hour.</p>
     <table class="bigTable"><tr><th>Ants</th><th>Bread moved in an hour</th><th>Pieces lost to a bird</th></tr>
     <tr><td>a single ant working alone</td><td>2 crumbs</td><td>2</td></tr>
     <tr><td>a line of forty ants from one colony</td><td>the whole piece</td><td>0</td></tr></table>`,qs:["Which ants moved more bread in the hour?","Make an argument that working as a colony helps an ant survive. Use something from the table.","Name one other way living in a group could help an animal stay alive."],key:["the line of forty, which moved the whole piece against 2 crumbs (3-LS2-1)","The claim yes, with the evidence attached: forty ants moved the whole piece and lost none to a bird, while the single ant moved 2 crumbs and lost 2 pieces, so a colony brings far more food home. A yes with no number or fact from the table is not yet an argument. (3-LS2-1)","Any sound second reason: defending the nest together, caring for the young, carrying loads no one ant could move, passing word of food to the others, keeping the nest at the right temperature. (3-LS2-1)"]}]},{id:21,title:"Litters and Seedlings",short:"Traits",parts:[{title:"Passed Down and Shaped",std:["3-LS3-1","3-LS3-2"],n:4,dur:120,dir:"Look at both tables. Answer out loud.",desc:"reading trait data for parents and offspring, naming the variation, and telling when the surroundings shaped a trait",html:()=>`<p class="big">Table 1: a cat with folded ear tips and her four kittens.</p>
     <table class="bigTable"><tr><th>Cat</th><th>Ear tips</th><th>Weight at ten weeks, in g</th></tr>
     <tr><td>mother</td><td>folded</td><td>3,900</td></tr>
     <tr><td>kitten A</td><td>folded</td><td>980</td></tr><tr><td>kitten B</td><td>folded</td><td>1,150</td></tr>
     <tr><td>kitten C</td><td>folded</td><td>1,040</td></tr><tr><td>kitten D</td><td>folded</td><td>910</td></tr></table>
     <p class="big">Table 2: two tomato seedlings from the same seed packet, planted on the same day.</p>
     <table class="bigTable"><tr><th>Seedling</th><th>Where it grew</th><th>Height after six weeks</th><th>Leaf color</th></tr>
     <tr><td>seedling 1</td><td>on a sunny window sill</td><td>22 cm</td><td>deep green</td></tr>
     <tr><td>seedling 2</td><td>on a shelf in a dim hallway</td><td>31 cm, thin and floppy</td><td>pale yellow green</td></tr></table>`,qs:["Every kitten has folded ear tips, the same as the mother. Where did that trait come from?","The kittens do not all weigh the same at ten weeks. What is that difference called. Does it mean one of them is not hers?","In Table 2 both seeds came from the same packet. What made one short and deep green and the other tall, thin and pale?","The taller plant is the weaker one. So is height always a sign of a good plant? Explain what shaped these two."],key:["It was inherited from the mother. A trait the parent has and every offspring has is passed down. (3-LS3-1)","Variation. They are all still her kittens: inherited traits vary from one offspring to the next, so a group of similar organisms is not identical. (3-LS3-1)","How much light each one got. Same seed packet, different surroundings, different plant. (3-LS3-2)","No. The plant in the dim hallway stretched toward what little light there was and stayed pale and weak, so its height came from its surroundings, not from being a better plant. Listen for the environment named as the cause. (3-LS3-2)"]}]},{id:22,title:"Stone and Survival",short:"Fossils",parts:[{title:"Clues at the Building Site",std:["3-LS4-1"],n:3,dur:90,dir:"Look at the table of rock layers. Answer out loud.",desc:"reading fossil data to say which organisms lived in a place and what the place was like",html:()=>`<p class="big">A digger cutting foundations for the new library turned up three layers of rock. A class listed what they found. The top layer is the youngest.</p>
     <table class="bigTable"><tr><th>Layer</th><th>Fossils found</th></tr>
     <tr><td>top</td><td>oak leaf prints, acorn shells</td></tr>
     <tr><td>middle</td><td>reed stems, a small fish, a pond snail</td></tr>
     <tr><td>bottom</td><td>clam shells, a shark tooth, sand ripples turned to stone</td></tr></table>
     <div class="figure">${F.icon("shell",80)}${F.icon("fish",80)}${F.icon("acorn",80)}</div>`,qs:["Name two organisms that once lived where this town now stands.","Was the bottom layer once an ocean or once a forest? Use the fossils as your evidence.","Put the three layers in order, oldest to youngest. Then say how the place changed over that time."],key:["Any two the table names: an oak, a reed, a fish, a pond snail, a clam, a shark. (3-LS4-1)","An ocean, or at least salt water. A shark tooth and clams belong in the sea, and the sand ripples show moving water. Naming them is the evidence. (3-LS4-1)","bottom, middle, top: from ocean, to a freshwater pond or marsh, to dry land with oak trees. Order and the change both have to be there. (3-LS4-1)"]},{title:"A Useful Difference",std:["3-LS4-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"explaining how a variation among individuals of one species gives an advantage",html:()=>`<p class="big">Finches at the park feeder eat seeds, and this winter only the hard-shelled seeds were left. A class measured beaks and watched the birds eat.</p>
     <table class="bigTable"><tr><th>Finches</th><th>Beak depth</th><th>Hard seeds opened in a minute</th><th>Still at the feeder in spring, out of 25</th></tr>
     <tr><td>shallow beaks</td><td>8 mm</td><td>2</td><td>7</td></tr>
     <tr><td>deep beaks</td><td>12 mm</td><td>11</td><td>20</td></tr></table>`,qs:["Which finches opened more hard seeds in a minute?","Explain why a deep beak is an advantage in a winter when only hard seeds are left. Use the table.","The deep-beaked finches also raised more chicks that spring. How can a trait that helps a bird eat end up giving it more chicks?"],key:["the deep-beaked finches, 11 against 2 (3-LS4-2)","A deep beak cracks the hard shells, so those birds could still get food when the soft seeds ran out, and 20 of 25 were still there in spring against 7. The explanation has to lean on the data and has to tie the beak to the hard seeds. (3-LS4-2)","A bird that is well fed through winter survives to spring strong enough to find a mate and raise chicks. Accept any version that links surviving to finding mates or reproducing. (3-LS4-2)"]}]},{id:23,title:"The Creek Was Straightened",short:"Habitat",parts:[{title:"Who Survives, and What Would Help",std:["3-LS4-3","3-LS4-4"],n:4,dur:120,dir:"Read the table. Answer out loud.",desc:"arguing from data who can survive in a changed habitat, then judging the merit of a solution",html:()=>`<p class="big">The town straightened a bend out of the creek to make room for a new road. The water now runs fast and shallow with no pools. A class surveyed the creek before and after.</p>
     <table class="bigTable"><tr><th>Living thing</th><th>Before</th><th>After</th></tr>
     <tr><td>water moss on the rocks</td><td>a thin film</td><td>thick, over every rock</td></tr>
     <tr><td>small trout</td><td>24 counted</td><td>5 counted</td></tr>
     <tr><td>freshwater mussels</td><td>31 counted</td><td>none counted</td></tr></table>`,qs:["Which living thing survived well after the creek was straightened? Give the evidence.","Which one vanished from the creek completely. Which one hung on but did worse?","The class suggests dropping large boulders into the creek to slow the water and make pools again. Would that help the trout? Name one drawback.","A second plan is to dig the old bend back in. Which plan has more merit, and why?"],key:["The water moss. It went from a thin film to thick cover on every rock, so the fast shallow water suited it. (3-LS4-3)","The freshwater mussels could not survive there at all, from 31 down to none. The trout survived less well, from 24 down to 5. (3-LS4-3)","Yes, because boulders slow the water and make the pools trout need. Then any real drawback: it does not bring the mussels back on its own, boulders can be shifted by a flood, it is heavy work and costs money, it may make the water back up near the new road. A claim with no drawback is half of this standard. (3-LS4-4)","Either plan can earn credit. What is rated is the reasoning: digging the bend back restores the whole habitat, pools and slow edges and mussel beds together, but it costs far more and may take back land the road now uses, while boulders are cheap and quick and fix only part of it. (3-LS4-4)"]}]},{id:24,title:"Weather and Climate",short:"Weather",parts:[{title:"A Season of Weather",std:["3-ESS2-1"],n:3,dur:90,dir:"Look at the table. Answer out loud. For the last one, draw your graph on your paper and hold it up.",desc:"reading and making a graphical display of typical weather for one season",html:()=>`<p class="big">A class kept a weather board for the first four weeks of the year and counted the kind of day each week brought.</p>
     <table class="bigTable"><tr><th>Week</th><th>Rainy days</th><th>Foggy days</th><th>Clear days</th></tr>
     <tr><td>1</td><td>4</td><td>2</td><td>1</td></tr>
     <tr><td>2</td><td>3</td><td>3</td><td>1</td></tr>
     <tr><td>3</td><td>5</td><td>1</td><td>1</td></tr>
     <tr><td>4</td><td>2</td><td>4</td><td>1</td></tr></table>
     <div class="figure">${F.icon("rain",88)}${F.icon("cloud",88)}</div>`,qs:["Across all four weeks, which kind of day happened most often? Work it out from the table.","What would you tell a visitor to expect in a typical week of this season?","Draw a bar graph with one bar for each kind of day, using the four-week totals. Label both sides."],key:["rainy days, 14 in all against 10 foggy and 4 clear (3-ESS2-1)","Mostly wet and gray: about two to five rainy days, a few foggy days, and about one clear day a week. Any description that uses the table and gives a typical week rather than one week. (3-ESS2-1)","Three bars with heights that match 14 rainy, 10 foggy and 4 clear, a label on the kind-of-day side and a label on the number-of-days side. A graph with no labels is incomplete. (3-ESS2-1)"]},{title:"Two Parts of the World",std:["3-ESS2-2"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"combining information to describe the climates of two different regions of the world",html:()=>`<p class="big">The same month, the first month of the year, in two regions on opposite halves of the globe.</p>
     <table class="bigTable"><tr><th>Region</th><th>Average temperature that month</th><th>Season there</th><th>Rain that month</th></tr>
     <tr><td>a region on the northern half</td><td>7 C</td><td>winter</td><td>11 cm</td></tr>
     <tr><td>a region on the southern half</td><td>24 C</td><td>summer</td><td>3 cm</td></tr></table>
     <div class="figure">${F.icon("globe",80)}${F.icon("sun",80)}</div>`,qs:["In the same month, one region is in winter and the other is in summer. What does the table say about their temperatures?","How can two regions be in different seasons at the same time?","Give one other reason why two regions of the world end up with different climates."],key:["The northern region averages 7 C and the southern region 24 C, a difference of 17 degrees in the very same month. (3-ESS2-2)","Because the two halves of the globe tilt toward the sun at different times of the year, so when one half is having its winter the other is having its summer. Accept the idea of the tilt in the student’s own words. (3-ESS2-2)","Any other sound reason: how near a region is to the middle of the globe, how high it sits above sea level, how near it is to an ocean, whether mountains block the rain. (3-ESS2-2)"]},{title:"Ready for the Flood",std:["3-ESS3-1"],n:3,dur:90,dir:"Answer out loud.",desc:"making a claim about the merit of a design that reduces the impact of a weather hazard",html:()=>`<p class="big">When a long rain falls, water runs off the hard parking lot. It floods the street at the bottom of the hill. The town digs a shallow dish of ground beside the lot. They fill it with gravel. They plant it with deep-rooted grasses. So the runoff gathers there and soaks in.</p>
     <div class="figure">${F.icon("rain",88)}${F.icon("sprout",88)}</div>`,qs:["Which weather hazard is this design built to reduce?","Make a claim. Does the planted dish have merit? Give your reason.","Name one thing this design does not protect the street from."],key:["street flooding when a long rain runs off hard ground (3-ESS3-1)","Yes, with a reason attached: the water gathers in the dish and soaks into the gravel and soil instead of running down the street. A yes with no reason is not yet a claim. (3-ESS3-1)","Any real limit: a rain heavier than the dish can hold, water coming from somewhere else, the gravel clogging with silt over time, flooding from the creek itself, wind damage, the ground already being soaked from the day before. (3-ESS3-1)"]}]},{id:25,title:"Pushes in the Hall",short:"Forces",parts:[{title:"Balanced or Not",std:["3-PS2-1"],n:4,dur:105,dir:"Answer out loud.",desc:"planning an investigation of balanced and unbalanced forces acting on an object",html:()=>`<p class="big">Two people are moving a long, heavy table across the hall floor. One pushes from the west end and one pushes back from the east end. The table does not budge.</p>
     <div class="figure">${F.icon("hands",96)}${F.icon("box",80)}</div>`,qs:["Are the forces on the table balanced or unbalanced? How do you know?","The person at the east end steps away. What happens, and what changed about the forces?","Plan an investigation to find out. Is the table easier to slide on the wood floor? Or on the carpet? What will you change? What will you measure?","What stays the same from one test to the next?"],key:["Balanced. Two equal pushes in opposite directions add up to no change in motion, and the table staying still is the evidence. (3-PS2-1)","The table slides east. Nothing balances the push from the west end now, so the forces are unbalanced. (3-PS2-1)","A plan with one thing changed and one thing measured: push the same table over the wood floor and then over the carpet (the change) and read a pull scale, or time how long it takes to cross a marked distance (the measure). (3-PS2-1)","Any controlled variable that fits the plan: the same table, the same load on it, the same distance, the same pusher, the same steady effort. (3-PS2-1)"]},{title:"Predict the Next Mark",std:["3-PS2-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a pattern in motion data to predict where an object will be later",html:()=>`<p class="big">A class rolls a toy car down a long ramp and across the hall floor. Tape marks sit every 50 cm along the floor, and a timer calls out each second.</p>
     <table class="bigTable"><tr><th>Seconds on the floor</th><th>Distance from the ramp</th></tr>
     <tr><td>1</td><td>100 cm</td></tr><tr><td>2</td><td>180 cm</td></tr>
     <tr><td>3</td><td>240 cm</td></tr><tr><td>4</td><td>280 cm</td></tr></table>`,qs:["Is the car covering the same distance in every second, or less each time? Use the numbers.","Look at how much is added each second: 80, then 60, then 40. What would you predict for the fifth second. What do you think happens after that?","What is causing the car to behave this way on the floor?"],key:["Less each time. The gaps shrink: 100, then 80 more, then 60 more, then 40 more. The car is slowing down. (3-PS2-2)","About 20 cm more, so around 300 cm, and then the car stops, because the next step in the pattern would be nothing added. Accept any answer the student reaches by continuing the pattern and explaining it. (3-PS2-2)","Friction between the wheels and the floor is a force acting against the motion, so the car loses speed until it stops. Accept rubbing or drag named in the student’s own words. (3-PS2-2)"]}]},{id:26,title:"Pulling Without Touching",short:"Magnets",parts:[{title:"Ask About the Pull",std:["3-PS2-3"],n:3,dur:90,dir:"Answer out loud. Your two questions have to be questions, not statements.",desc:"asking questions about cause and effect in electric or magnetic interactions between objects not touching",html:()=>`<p class="big">A wool sweater is pulled off over someone’s head. The hall is dry. Afterwards a comb is rubbed on that sweater. The comb is held above a pile of torn paper bits. The bits jump up to the comb without being touched.</p>
     <div class="figure">${F.icon("eraser",80)}${F.icon("books",80)}</div>`,qs:["The comb never touches the paper bits, yet they jump. What does that tell you about this force?","Name two questions about it you could settle by trying something.","The same comb does nothing at all on a damp rainy day. What does that tell you about what this force depends on?"],key:["The force acts across a distance, with no contact between the objects. (3-PS2-3)","Any two real investigable questions: how long does the comb have to be rubbed, how high can it be held and still lift a bit, do bigger pieces of paper jump, does a plastic ruler work instead, does rubbing on cotton work as well as wool. A statement is not a question, so ask once more. (3-PS2-3)","The effect depends on conditions, not only on the comb. Damp air lets the charge leak away, so the cause of the pull is a charge that dry air holds and wet air does not. (3-PS2-3)"]},{title:"A Problem for a Magnet",std:["3-PS2-4","3-5-ETS1-1"],n:4,dur:105,dir:"Answer out loud. For the third one you may write your two sentences on your paper.",desc:"defining a design problem that magnets can solve, with criteria for success and constraints",html:()=>`<p class="big">The hall has a recycling table. Steel cans and aluminum cans go in different bins. Sorting them by hand takes two people all morning.</p>
     <div class="figure">${F.icon("box",88)}${F.icon("key",72)}</div>`,qs:["Say the problem in one sentence that begins: The problem is.","Why is a magnet a sensible idea here? A magnet pulls steel but not aluminum. How does that help you sort?","Write two things your sorter must do for you to call it a success.","You may use three things only. One magnet, a cardboard chute, and tape. It has to be ready by Friday. What limits does that put on your design?"],key:["A problem statement about sorting steel cans from aluminum cans faster or with fewer people. The problem has to be about the sorting, not about recycling in general. (3-PS2-4)","Pass all the cans by a magnet. The steel ones are pulled aside and the aluminum ones are not, so the two kinds separate themselves without anyone reading a label. (3-PS2-4)","Two criteria, written as what the sorter must do: put every steel can in the steel bin, let no aluminum can into the steel bin, work faster than two people by hand, work without anyone touching the cans. (3-5-ETS1-1)","Names the limits as limits: only those materials, only one magnet, and the time limit of Friday. Materials, time and cost are the constraints to listen for. (3-5-ETS1-1)"]}]},{id:27,title:"Compare and Test",short:"Design",parts:[{title:"Three Ways to Do It",std:["3-5-ETS1-2"],n:3,dur:90,dir:"Look at the table and the three rules. Answer out loud.",desc:"comparing several possible solutions against stated criteria and constraints",html:()=>`<p class="big">The hall garden club needs trays to start seeds in. Three designs are tried, twenty seeds in each.</p>
     <table class="bigTable"><tr><th>Design</th><th>Seeds that sprouted</th><th>Cost for one tray</th><th>Reusable next year?</th></tr>
     <tr><td>plastic tray with drain holes</td><td>18</td><td>4 dollars</td><td>yes</td></tr>
     <tr><td>paper cups with no holes</td><td>9</td><td>1 dollar</td><td>no</td></tr>
     <tr><td>wooden box lined with cloth</td><td>17</td><td>2 dollars</td><td>yes</td></tr></table>
     <p class="big">The rules for success: at least 15 of 20 seeds sprout, cost under 3 dollars, usable again next year.</p>`,qs:["Which design sprouted the most seeds?","Which tray meets all three rules? Explain using the table.","Pick a design you would not use. Then name the rule it fails."],key:["the plastic tray, 18 of 20 (3-5-ETS1-2)","The wooden box lined with cloth. 17 sprouted, it costs 2 dollars, and it can be used again. Another choice counts only if the student argues it against all three rules using the table. (3-5-ETS1-2)","Any reasoned rejection with the rule named: the plastic tray fails the cost rule at 4 dollars, the paper cups fail the sprouting rule at 9 and the reusable rule. Naming the rule is the part being rated. (3-5-ETS1-2)"]},{title:"Make the Test Fair",std:["3-5-ETS1-3"],n:3,dur:90,dir:"Answer out loud.",desc:"judging whether a test is fair, naming controlled variables, and identifying a failure point",html:()=>`<p class="big">Two watering amounts were tested to see which grows better seedlings.</p>
     <table class="bigTable"><tr><th>Tray</th><th>Water</th><th>Where it sat</th><th>Seeds planted</th></tr>
     <tr><td>tray 1</td><td>50 ml a day</td><td>sunny window</td><td>20</td></tr>
     <tr><td>tray 2</td><td>150 ml a day</td><td>dim shelf</td><td>12</td></tr></table>`,qs:["Is that a fair way to compare them? Explain.","Name two things that should have been kept the same.","Every seedling in tray 2 rotted at the base, right where the stem meets the soil. Name that weak spot. Then say what you would change about the design."],key:["No. Three things were different at once, the water, the light and the number of seeds, so better growth cannot be pinned on the watering. (3-5-ETS1-3)","Any two controlled variables: the same light, the same number of seeds, the same soil, the same tray, the same temperature, the same seed kind. (3-5-ETS1-3)","The failure point is rot at the base of the stem, which means too much water sitting at the soil surface. Any improvement aimed there: add drain holes, water less, water from below, use a soil that drains faster, let the top dry between waterings. An improvement somewhere else does not count. (3-5-ETS1-3)"]}]},{id:28,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-3.1"],n:4,dur:90,dir:"Use the map grid and the table. Answer out loud.",desc:"using a map grid and a table to describe physical and human features and where they sit",html:()=>`<p class="big">A map grid of the neighborhood around the community hall. North is the top row.</p>
     <table class="bigTable"><tr><th></th><th>west</th><th>middle</th><th>east</th></tr>
     <tr><th>north</th><td>${F.icon("mountain",54)}<br>low hill</td><td>${F.icon("tree",54)}<br>park</td><td>${F.icon("books",54)}<br>library</td></tr>
     <tr><th>middle</th><td>${F.icon("drop",54)}<br>creek</td><td>${F.icon("cabin",54)}<br>community hall</td><td>${F.icon("bread",54)}<br>bakery</td></tr>
     <tr><th>south</th><td>${F.icon("bridge",54)}<br>footbridge</td><td>${F.icon("bus",54)}<br>bus stop</td><td>${F.icon("sprout",54)}<br>garden plots</td></tr></table>
     <table class="bigTable"><tr><th>Place</th><th>Walking minutes from the hall</th></tr>
     <tr><td>bakery</td><td>3</td></tr><tr><td>bus stop</td><td>5</td></tr>
     <tr><td>library</td><td>8</td></tr><tr><td>low hill</td><td>16</td></tr></table>`,qs:["What lies directly south of the community hall?","Which two directions do you walk to get from the hall to the library?","Name one physical feature on this map and one thing people built.","Which place in the table takes longest to walk to? If you drew a bar graph of the table, how many bars would it have?"],key:["the bus stop (HSS-3.1)","north and east, in either order. The library sits in the north row and the east column. Partial: one of the two directions is approaching. (HSS-3.1)","Physical: the low hill, the creek. Human-made: the hall, the library, the bakery, the park, the footbridge, the bus stop, the garden plots. One of each is what is being checked. Partial: one of the two kinds named is approaching. (HSS-3.1)","the low hill, 16 minutes, and the graph would have four bars, one for each place in the table. Partial: the longest walk named with no answer about the number of bars is approaching. (HSS-3.1)"]}]},{id:29,title:"Long Ago in This Place",short:"Long Ago",parts:[{title:"The First Nations Here",std:["HSS-3.2"],n:3,dur:90,dir:"Answer out loud. Use what is on the screen and what you have learned.",desc:"describing how the languages of California’s American Indian nations are part of the land itself, and how a nation is part of the state today",html:()=>`<p class="big">Many California place names come from other languages. Those are the languages of the nations. These are their homelands. Rivers, mountains, valleys and towns carry words from those languages. They are all across the state. The words were there first. The names were written on a map long after.</p>
     <div class="figure">${F.icon("map",88)}${F.icon("speak",80)}</div>`,qs:["The screen says the words were in use long before the names were written on a map. Name two kinds of places in California that carry words from those languages. Then say whose languages those words come from.","A place can have its own name in a language. That language comes from the nation that lived there. What does that tell you about the place?","Is this only history? Give one way a nation is part of California in the present."],key:["Any two of rivers, mountains, valleys, and towns. The words come from the languages of the American Indian nations whose homelands those places are. Partial: two kinds of places named with nothing said about whose languages the words come from is approaching. (HSS-3.2)","That people were living there, naming the land and knowing it, long before anyone drew it on a map, and that their language is still part of the place today. Partial: saying people lived there with nothing said about the language still being part of the place is approaching. (HSS-3.2)","No. Any true present-day answer: nations have their own tribal governments, there are language classes and cultural centers, nations care for land and water, people hold cultural events, members live and work across the state. Partial: saying no with no present-day example is approaching. (HSS-3.2)","Not scored, ask it anyway: which American Indian nation or nations have their homeland where this student lives? The answer is different for every family, so there is no key for it and it stays out of the rating. Tell the student the name if they do not know it, write it on the record sheet, and make it something to teach before the next check."]},{title:"A Town Over Time",std:["HSS-3.3"],n:3,dur:90,dir:"Look at the timeline. Answer out loud.",desc:"sequencing local historical events and describing the mark each period left on the land",html:()=>`<p class="big">A timeline for the town of Bell Crossing.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1848</td><td>a wagon road crosses the creek at the shallow ford</td></tr>
     <tr><td>1872</td><td>a brickworks digs clay from the creek bank</td></tr>
     <tr><td>1910</td><td>a streetcar line runs out from the ford, and houses go up along it</td></tr>
     <tr><td>1955</td><td>the streetcar is taken out and the rails are paved over</td></tr>
     <tr><td>2016</td><td>the old clay pit is filled and turned into the garden plots</td></tr></table>
      <p class="big">Nobody wrote this timeline down at the time. It was put together from a hand-drawn map of 1848, a photograph of the brickworks crew, a bundle of letters a brickmaker sent home, old copies of the town newspaper, and a recording of an old woman remembering the streetcar. Those are called primary sources, because they come straight from the people who were there.</p>`,qs:["Put these three in order, earliest first: the streetcar line, the wagon road, the brickworks.","Which event changed the creek bank. What did it do to it?","This timeline was built from primary sources. Name two of the primary sources listed. One source is something a person there made. Another is a story told at second hand. Say why the first is worth more to a historian."],key:["wagon road, brickworks, streetcar line. Partial: two of the three in the right order is approaching. (HSS-3.3)","the brickworks in 1872, which dug a clay pit out of the bank. Partial: naming the brickworks with no account of what it did to the bank is approaching. (HSS-3.3)","Any two from the page: the 1848 hand-drawn map, the photograph of the brickworks crew, the brickmaker’s letters, the old newspapers, the recording of the woman remembering the streetcar. For the second part, accept any sense of the idea that the person was there and saw it, so less has been changed, left out or guessed at in the retelling. Partial: two sources named with no account of why a first-hand source is worth more is approaching. (HSS-3.3)"]}]},{id:30,title:"Rules and Work",short:"Rules",parts:[{title:"Rules, Laws and Government",std:["HSS-3.4"],n:4,dur:105,dir:"Answer out loud.",desc:"telling rules from laws and naming the basic parts and levels of United States government",html:()=>`<p class="big">A town council meets in the hall. They talk about a new speed limit. It is for the street outside the park.</p>
     <div class="figure">${F.icon("books",88)}${F.icon("flag",88)}</div>`,qs:["A speed limit set by the town council is a law. How is that different from a rule the hall posts on its own door?","How do the people of a town get a say in the laws the council makes?","The United States government has three parts. Name the part that makes laws and the part that decides what a law means.","Name two different levels of government that could set a speed limit on a road."],key:["A law is made by a government, applies to everyone on that street, and the government decides what happens when it is broken. A posted rule is set by whoever runs the hall and applies only inside. Partial: one of the two halves described is approaching. (HSS-3.4)","They vote for the council members, and they can speak at a council meeting or write to them. Accept voting, speaking up, or contacting a representative. Partial: naming voting with nothing else a resident can do is still proficient; saying only that people can complain, with no route to the council, is approaching. (HSS-3.4)","the legislative branch, Congress or the state legislature, makes laws, and the judicial branch, the courts, decides what a law means. Partial: one of the two parts named is approaching. (HSS-3.4)","Any two of: the town or city, the county, the state, the national government. Partial: one level of government named is approaching. (HSS-3.4)"]},{title:"Choices and the Local Economy",std:["HSS-3.5"],n:4,dur:105,dir:"Look at the table. Answer out loud.",desc:"basic economic reasoning about producers, consumers, specializing and goods and services",html:()=>`<p class="big">A new bakery opens next door to the hall. The baker buys flour from a mill in the next county and sells bread to people in town. She also teaches a bread class on Saturdays.</p>
     <table class="bigTable"><tr><th>Who</th><th>What they do in this chain</th></tr>
     <tr><td>the farmer</td><td>grows the wheat</td></tr>
     <tr><td>the mill</td><td>grinds wheat into flour</td></tr>
     <tr><td>the baker</td><td>bakes the flour into bread</td></tr>
     <tr><td>a family in town</td><td>buys and eats the bread</td></tr></table>
      <p class="big">Making bread takes three kinds of resource. Natural resources are the things that come from the earth, like the soil and the water the wheat grows in. Human resources are the people and their skill, like the farmer and the baker. Capital resources are the tools and buildings people made in order to work, like the mill and the oven.</p>`,qs:["Who in this table is the consumer, and who are the producers?","The baker does not grow her own wheat or grind her own flour. Why is it better for each of them to do just one job?","She sells bread and she teaches a class. Which is a good and which is a service?","Making bread uses natural resources, human resources and capital resources. Give one example of each from this chain."],key:["The family in town is the consumer. The farmer, the mill and the baker are all producers. Partial: the consumer named with one producer missed is approaching. (HSS-3.5)","Each one gets good at one job and has the right land, machines or skill for it, so the work is faster and better than if everyone did all of it. Accept specializing explained in the student’s own words. Partial: saying it is quicker with no account of skill, land or equipment is approaching. (HSS-3.5)","Bread is a good, something you can hold. Teaching a class is a service, work someone does for you. Partial: one of the two sorted right is approaching. (HSS-3.5)","Natural: the soil or the water the wheat grows in. Human: the farmer, the mill worker or the baker, and their skill. Capital: the mill or the oven, and accept the bakery building. One of each is what is being checked. Partial: two of the three kinds given is approaching. (HSS-3.5)"]}]}];const WC=FLU.split(/\s+/).filter(Boolean).length;const readPart=STOPS[2].parts[0];readPart.n=WC;readPart.key[0]=readPart.key[0].replace("__WC__",WC);readPart.desc=`a ${WC}-word grade-level story read aloud`;const LEVELUPS={4:{id:"L4",title:"Level Up: Put It Together",std:["RI.4.1"],needs:["RI.3.1"],n:2,dir:"Answer out loud. Use details and examples from the text.",html:()=>`<ol class="qlist"><li>The text never says that a star could stop shining and we would still see it for years. Use details from the text to explain why that could happen.</li><li>Light from one star takes 4 years to reach us. Light from another star takes 900 years. Which star are you seeing more out of date? Use the text to explain.</li></ol>${lightHtml(true)}`,key:["Because the light we see left the star long ago and takes years to cross the distance, so light that is already on its way would keep arriving after the star changed. Details: light takes years to reach us, and some starlight left before you were born. The text never states this, so the student has to put the details together. (RI.4.1, inference backed by details and examples)","The one whose light takes 900 years. Its light left 900 years ago, while the other star's light left about 4 years ago, so the farther star is the one you are seeing further out of date. Detail from the text: Proxima Centauri's light takes a little more than four years, and many stars are much farther away than that. (RI.4.1, inference with details)"]},5:{id:"L5",title:"Level Up: Unlike Pieces",std:["4.NF.A.2"],needs:["3.NF.A.3"],n:3,dir:"Answer out loud and tell how you know. You can write on your paper.",html:()=>`<ol class="qlist"><li>Which is greater, 2/3 of a lantern or 3/5 of the same lantern?</li><li>Write &gt;, &lt;, or = to make it true: 5/8 ____ 1/2</li><li>Is 4/9 of a lantern more or less than half a lantern? Use half as your benchmark.</li></ol>`,key:["2/3. In fifteenths, 2/3 is 10/15 and 3/5 is 9/15, so 2/3 is greater. (4.NF.A.2, comparing fractions with different numerators and denominators)","5/8 &gt; 1/2. In eighths, 1/2 is 4/8, and 5/8 is more than 4/8. (4.NF.A.2)","Less than half. Half of 9 is 4.5, so 4/9 is just under half. Accept the comparison in eighteenths: 4/9 is 8/18 and 1/2 is 9/18. (4.NF.A.2, comparing to a benchmark)"]},6:{id:"L6",title:"Level Up: Read Between the Lines",std:["RL.4.1"],needs:["RL.3.1"],n:2,dir:"Answer out loud. Use details from the story.",html:()=>`<ol class="qlist"><li>The story never says that Tariq was proud in the spring. How do you know that he was? Give two details from the story.</li><li>Why do you think Tariq did not want to write his goal down at first? Use a detail from the story.</li></ol>${F.passage(STORY,STORY_TITLE,true)}`,key:["He was proud, backed by two details: he read the card twice, he had reached the far wall three times in July, and he kept the card in his pocket all the next week. (RL.4.1, inference with details)","He was not sure he could do it, because last summer he had only made it halfway, so writing the goal down meant he might not reach it. The detail about halfway is the evidence. (RL.4.1, inference with a detail)"]},7:{id:"L7",title:"Level Up: Around and Across",std:["4.MD.A.3"],needs:["3.MD.C.7"],n:3,dir:"Solve on your paper and hold it up.",html:()=>`<ol class="qlist"><li>A lantern banner is 9 feet long and 4 feet tall. What is its area? What is its perimeter?</li><li>A rectangular deck has an area of 56 square feet. One side is 7 feet long. How long is the other side, and what is the perimeter?</li><li>A rail runs all the way around a rectangle that is 24 meters by 15 meters. The rail comes in 6 meter pieces. How many pieces are needed?</li></ol>`,key:["Area 36 square feet, from 9 × 4. Perimeter 26 feet, from 9 + 4 + 9 + 4, or 2 × 13. (4.MD.A.3)","The other side is 8 feet, because 7 × 8 = 56. Perimeter 30 feet, from 2 × (7 + 8). (4.MD.A.3, area formula with an unknown factor)","13 pieces. The perimeter is 2 × (24 + 15) = 78 meters, and 78 ÷ 6 = 13. (4.MD.A.3)"]},10:{id:"L10",title:"Level Up: Grown-Up Grammar",std:["L.4.1"],needs:["L.3.1"],n:3,dir:"Say each answer out loud.",html:()=>`<ol class="qlist"><li>Which sentence is right? A: We should of hung the lanterns earlier. B: We should have hung the lanterns earlier.</li><li>Put these words in the order that sounds right in English: <b>two / paper / small / lanterns</b></li><li>Change this sentence so it tells what is happening right now: Mei lights the lantern.</li></ol>`,key:["B. “Should of” is not a correct form, so the modal auxiliary needs have. (L.4.1, modal auxiliaries and common usage errors)","two small paper lanterns. Number, then size, then what it is made of, then the noun. (L.4.1, ordering adjectives within a sentence)","Mei is lighting the lantern. (L.4.1, present progressive verb tense)"]}};const PASSAGE_STD=["RL.3.1","RL.3.4","RI.3.1","RI.3.9","W.3.8","RL.4.1","RI.4.1"];const MULT_N=10;const FRAC_DENS=[1,2,3,4,5,6,8];let multSel=[0,0],fracOn={};function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function fracHtml(){return FRAC_DENS.map(d=>{const on=fracOn[d]||0;let r=`<div class="fs-row">`;for(let k=0;k<d;k++)r+=`<button class="fs-part${k<on?" on":""}" data-d="${d}" data-k="${k}">${d===1?"1 whole":"1/"+d}</button>`;return r+"</div>"}).join("")+`<p class="small">Click a piece to shade up to it. Click the last shaded piece to clear the row.</p>`}function lineHtml(){const rows=[[2,"halves"],[3,"thirds"],[4,"fourths"],[6,"sixths"],[8,"eighths"]];return`<div style="display:flex;flex-direction:column;gap:6px">`+rows.map(r=>`<div style="text-align:center"><p class="fig-label" style="margin:0">0 to 1 in ${r[1]}</p>${F.numberLine({min:0,max:1,step:1/r[0],hideNumbers:true,ticks:[[0,"0"],[1,"1"]],width:520})}</div>`).join("")+`</div><p class="small">Count the equal spaces, not the tick marks. The 0 tick is where you start counting from.</p>`}function areaHtml(){return F.table(["What to find","How"],[["Area of a rectangle","length × width, answer in square units"],["Area of an L shape","cut it into rectangles, find each area, add them"],["A missing side","area ÷ the side you know"],["Perimeter","add all four sides, or 2 × (length + width)"]])+`<p class="small">Area counts the squares inside. Perimeter measures the trip around the outside.</p>`}const SENT_SET={opinion:"opinion",facts:"facts",story:"story","W.3.1":"opinion","W.3.2":"facts","W.3.3":"story","W.3.8":"W.3.8","SL.3.2":"SL.3.2","SL.3.4":"SL.3.4","RI.3.9":"RI.3.9"};function sentSet(st){const ps=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];for(const p of ps){const a=p.alt&&p.alt.key||p.wk||p.wt;if(a&&SENT_SET[a])return SENT_SET[a];const hit=(p.std||[]).find(c=>SENT_SET[c]);if(hit)return SENT_SET[hit]}return"opinion"}function starters(st){const k=sentSet(st);if(k==="story")return["On a clear night, ____.","First, ____.","Next, ____.","“____,” said ____.","Finally, ____."];if(k==="facts")return["Starlight is called old light because ____.","One fact is ____.","Also, ____.","Another fact is ____.","Now you know ____."];if(k==="W.3.8")return["The text says ____.","Speed: ____.","Distance: ____."];if(k==="SL.3.2")return["The big idea is ____.","One detail is ____.","Another detail is ____.","The graph shows ____."];if(k==="SL.3.4")return["I want to tell you about ____.","It happened ____.","One thing I remember is ____.","That is why ____."];if(k==="RI.3.9")return["Both texts say ____.","Old Light measures it in ____.","Counting the Years measures it in ____.","Only the second text says ____."];return["The town should pick ____ because ____.","One reason is ____.","For example, ____.","That is why ____."]}function sentHtml(st){return`<ul class="starters">${starters(st).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["3.OA.A.1","3.OA.A.2","3.OA.D.8","3.MD.C.7","4.MD.A.3"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const row=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===row&&multSel[1]===k?[0,0]:[row,k];r()})},nline:{name:"Fraction number lines",std:["3.NF.A.1","3.NF.A.2","3.NF.A.3","4.NF.A.2"],html:lineHtml},frac:{name:"Fraction strips",std:["3.NF.A.1","3.NF.A.3","3.G.A.2","4.NF.A.2"],html:fracHtml,bind:(b,r)=>b.querySelectorAll(".fs-part").forEach(x=>x.onclick=()=>{const d=+x.dataset.d,k=+x.dataset.k;fracOn[d]=fracOn[d]===k+1?0:k+1;r()})},area:{name:"Area and perimeter card",std:["3.MD.C.7","3.G.A.2","4.MD.A.3"],html:areaHtml},sent:{name:"Sentence starters",std:["W.3.1","W.3.2","W.3.3","W.3.8","SL.3.2","SL.3.4","RI.3.9"],html:sentHtml}};const SUP_CAVEATS=[{t:"mult",std:["3.MD.C.7","4.MD.A.3"],msg:"The multiplication chart gives the products, so rate on whether the student sets the problem up as area or perimeter and uses square units, not on the fact itself."},{t:"nline",std:["3.NF.A.2"],msg:"The number line tool already shows the equal spaces from 0 to 1, so the partitioning is done for the student. Rate on whether the student can name the point as a fraction and say what one space is called."},{t:"nline",std:["3.NF.A.3","4.NF.A.2"],msg:"Lined-up number lines let the student see which fraction is farther from 0, so count the comparisons as supported, not independent."},{t:"frac",std:["3.NF.A.3"],msg:"Fraction strips show the piece sizes and the equal shading, so rate on whether the student can explain what the strips show rather than on the comparison itself."},{t:"frac",std:["3.G.A.2"],msg:"The strips show equal parts already made, so rate on whether the student names one part as a unit fraction of the whole."},{t:"area",std:["3.MD.C.7","3.G.A.2","4.MD.A.3"],msg:"The card gives the method for area, perimeter, a missing side, and cutting an L shape apart. Count those items as supported, not independent."},{t:"sent",std:["W.3.1","W.3.2","W.3.3"],msg:"Sentence starters supply the opening, the linking words, and the closing, so count those checks as supported, not independent."},{t:"sent",std:["W.3.8"],msg:"Sentence starters give the student the note categories, so rate on the facts chosen and on how brief the notes are."},{t:"sent",std:["SL.3.2"],msg:"The frames name main idea and detail for the student, so rate on whether the content of each answer is right."},{t:"passage",std:["RL.3.1","RL.3.4","RI.3.1","W.3.8","RL.4.1","RI.4.1"],msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"passage",std:["RI.3.9"],msg:"Comparing two texts starts with reading both. If either text was read to the student, this stop shows listening, not reading."},{t:"mult",std:["3.OA.A.1","3.OA.A.2"],msg:"The multiplication chart gives the totals and the missing factors, so rate on whether the student can say what the numbers mean in the crate story, not on the fact itself."},{t:"mult",std:["3.OA.D.8"],msg:"With the chart the arithmetic is handed over. Rate on whether both steps are there and whether the equation uses a letter for the unknown."},{t:"frac",std:["3.NF.A.1"],msg:"The fraction strips show the equal parts already cut, so rate on whether the student can say what the top number and the bottom number each mean."},{t:"sent",std:["SL.3.4"],msg:"Sentence starters supply the opening and the closing of the report, so count those checks as supported, not independent."},{t:"sent",std:["RI.3.9"],msg:"The frames name the comparison for the student, so rate on whether the content of each answer is right."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
